from click.testing import CliRunner

CASES = [
    ("is_flag+composite type", ["--flag"], dict(is_flag=True, type=(str, int))),
    ("is_flag+multiple+composite", ["--flag"], dict(is_flag=True, multiple=True, type=(str, int))),
    ("is_flag+default=0", ["--flag"], dict(is_flag=True, default=0)),
    ("flag_value+multiple", ["--upper", "transformation"], dict(flag_value="upper", multiple=True)),
    ("is_flag+default='x'", ["--flag"], dict(is_flag=True, default="x")),
    ("is_flag+prompt", ["--flag"], dict(is_flag=True, prompt=True)),
    ("is_flag=False+flag_value+multiple", ["--name"], dict(is_flag=False, flag_value="Flag", multiple=True)),
]
for name, decls, kwargs in CASES:
    try:
        @click.command()
        @click.option(*decls, required=True, **kwargs)
        def cli(**kw):
            click.echo(repr(kw))
